GLOSSARY = {
    "sentinel2": ("Sentinel-2", "A pair of European satellites that photograph all land every five days in 13 colour bands, at 10 to 20 m per pixel. The data is free."),
    "landsat": ("Landsat 8 and 9", "US satellites that, among other things, measure how warm the ground is, at about 100 m per pixel. Free."),
    "srtm": ("SRTM", "A global elevation map made from a Space Shuttle radar flight in 2000, at 30 m per pixel."),
    "band": ("Band", "One slice of the spectrum measured by a satellite sensor, such as blue, red or near infrared. Each band gives one number per pixel."),
    "reflectance": ("Surface reflectance", "The share of sunlight a surface reflects in one band, from 0 to 1, after the effect of the atmosphere is removed."),
    "composite": ("Median composite", "For each pixel, the middle value of all its cloud-free observations in a period. It removes clouds, shadows and one-day events."),
    "ndvi": ("NDVI", "A greenness index from the red and near-infrared bands. High on crops and trees, near zero on bare ground, waste and roofs."),
    "ndbi": ("NDBI", "A built-up index from the short-wave and near-infrared bands. High on roofs, paving and bare or disturbed ground."),
    "bsi": ("BSI", "A bare-soil index from four bands. High on bare ground, lower on roofs, so it helps separate the two."),
    "lst": ("Land surface temperature", "How warm the ground surface is, measured from thermal infrared. Dumps are usually warmer than their surroundings: dark, dry, and decomposing."),
    "anomaly": ("Temperature anomaly", "A pixel's surface temperature minus the mean of the land within 2 km. It removes regional climate, so places in different states can be compared."),
    "premonsoon": ("Pre-monsoon", "March to May, the hot dry season before the rains. Skies are clear and fields are mostly bare."),
    "winter": ("Winter season", "Mid-November to mid-February, when the winter (rabi) crop is growing and farmland is green."),
    "lookalike": ("Look-alike", "A place that is not a dump but resembles one from above: a quarry, an ash pond, bare ground. Used in training as a hard example of what not to flag."),
    "nearsite": ("Near-site background", "Points drawn at random from the 15 km box around each training landfill. They show the model what the land around a city dump looks like."),
    "random": ("Random background", "Points drawn at random across the states that supply training sites, at least 500 m from any mapped site."),
    "place": ("Place", "Outlines within 500 m of each other are treated as one place, so two cells of the same dump are never split between training and testing."),
    "region": ("Zonal Council region", "India's states are grouped by law into six zones: Northern, Central, Eastern, Western, Southern and North-Eastern. They are used here as six validation folds."),
    "leakage": ("Leakage", "When test rows are near-copies of training rows, for example two pixels of the same dump. The score then measures memory, not skill."),
    "heldout": ("Held-out region", "A validation round in which every place in one region is removed from training and used only for testing. Six rounds, one per region."),
    "prf": ("Precision, recall, F1", "Recall: of the real landfill pixels, the share flagged. Precision: of the flagged pixels, the share that are landfill. F1 is their harmonic mean."),
    "score": ("Model score", "The model's output for a pixel, between 0 and 1. A pixel is flagged at 0.5 or above. It is not the probability that the place is a dump."),
    "threshold": ("Threshold", "The score at or above which a pixel is flagged. Fixed at 0.5 before any result was seen."),
    "freeze": ("Freeze", "The commit in which the model, its threshold and the scoring rules were fixed. It carries a Git tag, pushed before Gujarat was scored."),
    "sealed": ("Sealed test list", "The list of known Gujarat dumpsites with their outlines, committed before any model was run and not used in training."),
    "found": ("Site found", "A known site counts as found when at least half of the pixels inside its outline are flagged."),
    "patch": ("Alarm patch", "A group of touching flagged pixels covering at least 1 ha. It is the unit someone would go and look at."),
    "rank": ("Rank", "Alarm patches are ordered by their mean score, strongest first. Rank 1 is the patch the model is most sure of."),
    "handcheck": ("Hand check", "Looking at each of the top alarm patches in high-resolution imagery and recording what is there, without seeing its score or rank."),
    "auc": ("AUC of one feature", "The chance that a randomly chosen landfill pixel has a higher value of that feature than a randomly chosen pixel of another class. 0.5 means the feature carries no information; 0 or 1 means it separates them completely."),
    "purity": ("Neighbour purity", "For one point, the share of its 15 most similar points (from other places) that are landfill. It measures overlap between classes without any model."),
    "pca": ("Principal components", "A way of squeezing many variables into a few new ones that keep as much of the variation as possible, so the data can be drawn in two dimensions."),
    "shap": ("SHAP", "A method that divides one prediction among the features that produced it. Summed over many points it shows what the model relies on."),
    "novelty": ("Novelty", "How far a pixel lies from the training data, as a percentile of the training points' own distances to each other. Above the 99th percentile the model is extrapolating."),
    "prevalence": ("Prevalence", "How common the thing being looked for is. Landfill is 11% of the training points and about 0.02% of the land scored in Gujarat."),
    "gbm": ("Gradient boosting", "A model built from many small decision trees, each one correcting the errors of those before it."),
    "rf": ("Random forest", "A model that averages many decision trees, each trained on a random sample of the data and of the features."),
    "lr": ("Logistic regression", "A model that scores a pixel by a weighted sum of its features. The simplest of the learned models compared here."),
    "chip": ("Chip", "A small picture cut from the satellite composite, here 1.5 km across, showing what the model sees at 10 m per pixel."),
}
